<?php
declare(strict_types=1);define('NIB_EVENTOS_RUNTIME',true);require dirname(__DIR__).'/inscricoes/eventos-lib.php';
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');
try{$out=[];foreach(nibe_catalog() as $e){if(!empty($e['legacy'])||($e['publication']??'')!=='publicado')continue;$pr=$e['promotion']??['hero'=>false,'carousel'=>true,'events'=>false];$now=(new DateTimeImmutable('now',new DateTimeZone('America/Porto_Velho')))->format('Y-m-d\TH:i');$closed=!empty($e['registration_closed'])||!empty($e['registration_end'])&&$now>$e['registration_end'];$places=[];foreach(['hero','carousel','events'] as $k)$places[$k]=!empty($pr[$k])&&!($closed&&!empty($pr['remove_'.$k]));$out[]=['slug'=>$e['slug'],'name'=>$e['name'],'summary'=>$e['summary'],'start'=>$e['start'],'banner'=>$e['banner'],'url'=>nibe_page($e),'cta'=>$closed?'Ver informações':($e['cta']?:'Saiba mais'),'mode'=>$e['mode'],'open'=>nibe_open($e),'closed'=>$closed,'places'=>$places,'order'=>$e['order']??10];}usort($out,static fn($a,$b)=>$a['order']<=>$b['order']);echo json_encode(['events'=>$out],JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);}catch(Throwable $err){http_response_code(503);echo '{"error":"Divulgação temporariamente indisponível"}';}
